/* Purchasing the kiosk between shifts adds ordering capacity, never preparation capacity. */
POWERUPS.push({id:'kiosk',name:'Self-Service Kiosk',cost:35,icon:'kiosk',benefit:'From your next shift, choose Take order or Send to kiosk for each customer. Kiosk ordering takes 8 seconds.',strength:'Frees the barista from taking every order. Watch customers move into the pickup queue.',weakness:'Every third kiosk order fails and must be retaken at the counter. Does not speed up drinks or baking.'});
const KioskBase=CampaignCafe;
CampaignCafe=class extends KioskBase{
 get kioskEnabled(){return this.shift>1&&this.upgrades?.has('kiosk');}
 sendToKiosk(o=this.active){if(!this.kioskEnabled||this.finished||this.kioskJob||!o||!this.orders.includes(o)||o.accepted||o.kioskRetake)return false;this.kioskJob={id:o.id,started:this.time};return true;}
 accept(o=this.active){if(!o||this.kioskJob?.id===o.id)return false;const first=!o.accepted,ok=super.accept(o);if(ok&&first){o.orderTakenAt=this.time;if(o.kioskRetake){o.kioskRetake=false;this.kioskRetakes=(this.kioskRetakes||0)+1;}}return ok;}
 tick(dt){super.tick(dt);if(!this.kioskEnabled||this.finished||!this.kioskJob)return;const o=this.orders.find(o=>o.id===this.kioskJob.id);if(!o||o.accepted){this.kioskJob=null;return;}if(this.time-this.kioskJob.started<8)return;this.kioskJob=null;this.kioskAttempts=(this.kioskAttempts||0)+1;if(this.kioskAttempts%3===0){o.kioskRetake=true;this.kioskFaults=(this.kioskFaults||0)+1;}else{this.accept(o);o.orderedAtKiosk=true;this.kioskOrders=(this.kioskOrders||0)+1;}}
 serve(o=this.active,helper=false){const orderWait=o?Math.max(0,(o.orderTakenAt??this.time)-o.arrived):0;const r=super.serve(o,helper);if(r&&!r.rework){const result=this.served.at(-1);result.orderWait=orderWait;result.preparationWait=Math.max(0,result.wait-orderWait);}return r;}
 report(){const r=super.report();return {...r,orderWait:this.served.length?this.served.reduce((n,o)=>n+(o.orderWait||0),0)/this.served.length:0,kioskOrders:this.kioskOrders||0,kioskEnabled:!!this.kioskEnabled,kioskAttempts:this.kioskAttempts||0,kioskFaults:this.kioskFaults||0,kioskRetakes:this.kioskRetakes||0};}
};

const kioskPowerIcon=powerIcon,kioskPreview=preview;
powerIcon=function(u){return u.id==='kiosk'?'<svg viewBox="0 0 100 100" aria-hidden="true"><rect x="20" y="6" width="60" height="64" rx="8" fill="#4a484b" stroke="#513521" stroke-width="4"/><rect x="27" y="14" width="46" height="46" rx="3" fill="#e9f2d9"/><path d="M36 26h28M36 36h28" stroke="#bd976b" stroke-width="4"/><path d="M40 48l7 6 15-14" fill="none" stroke="#2b9b50" stroke-width="4"/><path d="M43 71v18H30v7h40v-7H57V71" fill="#746659"/></svg>':kioskPowerIcon(u);};
preview=function(u){return u.id==='kiosk'?'<div class="power-demo">'+powerIcon(u)+'<span>Order in 8s → join pickup queue</span></div>':kioskPreview(u);};
const kioskRender=render,kioskUpdate=update;
render=function(){kioskRender();if(!sim?.kioskEnabled)return;document.querySelector('.cafe-stage').insertAdjacentHTML('beforeend','<div class="kiosk-terminal" aria-label="Self-service kiosk">'+powerIcon({id:'kiosk'})+'<b>SELF ORDER</b><span id="kiosk-status" role="status">Ready</span><progress id="kiosk-progress" max="8" value="0"></progress></div><div class="queue-zone order-zone">Waiting to order <b id="ordering-count">0</b></div><div class="queue-zone pickup-zone">Waiting for pickup <b id="pickup-count">0</b></div>');document.querySelector('.cafe-stage').classList.add('has-kiosk');update();};
update=function(){kioskUpdate();if(!sim?.kioskEnabled||!document.querySelector('#kiosk-status'))return;const waiting=sim.orders.filter(o=>!o.accepted),pickup=sim.orders.filter(o=>o.accepted),job=sim.kioskJob,customer=sim.orders.find(o=>o.id===job?.id);document.querySelector('#ordering-count').textContent=waiting.length;document.querySelector('#pickup-count').textContent=pickup.length;document.querySelector('#kiosk-status').textContent=customer?`${customer.name} is ordering…`:`Ready · ${(sim.kioskAttempts||0)%3===2?'next use may fail':'choose a customer'}`;document.querySelector('#kiosk-progress').value=job?Math.min(8,sim.time-job.started):0;for(const el of document.querySelectorAll('[data-customer]')){const o=sim.orders.find(o=>o.id===+el.dataset.customer);if(!o)continue;const group=o.accepted?pickup:waiting,i=group.indexOf(o);el.style.left=(o.accepted?49-i*Math.min(6,14/Math.max(1,group.length-1)):24-i*Math.min(6,17/Math.max(1,group.length-1)))+'%';if(o.id===job?.id){el.querySelector('.customer-label small').textContent='Ordering at kiosk';el.style.left='12%';}else if(o.accepted)el.querySelector('.customer-label small').textContent=sim.ready(o)?'Ready for pickup':o.isRemake?'Remake in progress':'Waiting for preparation';}updateKioskRouting();};
const kioskBegin=beginCampaignShift;
beginCampaignShift=function(){kioskBegin();if(sim.kioskEnabled)document.querySelector('.learning-card p')?.insertAdjacentHTML('beforeend','<br><br><b>Your kiosk is open.</b> Choose Take order or Send to kiosk for each customer. Every third kiosk use fails: retake that order at the counter. Their original waiting clock continues. Keep an eye on both groups: ordering faster does not make the oven faster.');};
const kioskReport=showReport;
showReport=function(){kioskReport();const r=journey.reports.at(-1);if(r?.kioskEnabled)document.querySelector('.service-review')?.insertAdjacentHTML('beforeend',`<h3>Did the kiosk move the bottleneck?</h3><p>The kiosk completed <b>${r.kioskOrders} successful orders</b> from ${r.kioskAttempts} attempts. <b>${r.kioskFaults} faults</b> required counter retakes; ${r.kioskRetakes} were retaken. Served customers spent an average of <b>${r.orderWait.toFixed(1)}s</b> waiting to finish ordering and <b>${r.wait.toFixed(1)}s</b> from arrival to pickup. Compare these with the earlier shift. The kiosk adds ordering capacity; drink and oven capacity stay the same.</p>`);};

function updateKioskRouting(){if(!stationPanel&&sim.kioskJob?.id===sim.activeId){const next=sim.orders.find(c=>!c.accepted&&c.id!==sim.kioskJob.id);if(next){sim.select(next.id);selectedId=next.id;updateCloud(true);}}const o=sim.active,cloud=document.querySelector('#order-cloud');if(!o||!cloud)return;let send=document.querySelector('#send-kiosk');if(!o.accepted&&!send){send=document.createElement('button');send.id='send-kiosk';send.className='big-btn gold';send.textContent='Send to kiosk';cloud.appendChild(send);send.onclick=()=>{if(sim.sendToKiosk()){toast('Kiosk is taking this order. You can take another customer’s order now.');update();}};}if(send){send.hidden=!!o.accepted;send.disabled=!!sim.kioskJob||!!o.kioskRetake;send.textContent=o.kioskRetake?'Counter retake required':sim.kioskJob?.id===o.id?'Ordering at kiosk…':sim.kioskJob?'Kiosk busy':'Send to kiosk';}const take=document.querySelector('#take-order');if(take){take.disabled=sim.kioskJob?.id===o.id;take.textContent=o.kioskRetake?'Retake order at counter':take.disabled?'Ordering at kiosk…':'Take order at counter';}let alert=cloud.querySelector('.kiosk-error');if(o.kioskRetake&&!alert){alert=document.createElement('p');alert.className='kiosk-error';alert.setAttribute('role','status');alert.textContent='Order error—please retake my order. My waiting timer is still running.';cloud.prepend(alert);}else if(!o.kioskRetake)alert?.remove();for(const el of document.querySelectorAll('[data-customer]')){const c=sim.orders.find(c=>c.id===+el.dataset.customer);el.classList.toggle('kiosk-retake',!!c?.kioskRetake);if(c?.kioskRetake)el.querySelector('.customer-label small').textContent='Order error · retake at counter';}for(const el of document.querySelectorAll('[data-pick]')){const c=sim.orders.find(c=>c.id===+el.dataset.pick);if(c?.kioskRetake){el.textContent='⚠ Retake · '+c.name;el.classList.add('remake-ticket');}}}

const parallelKioskUpdate=update;
update=function(){parallelKioskUpdate();if(!sim?.kioskEnabled||sim.finished)return;let button=document.querySelector('#next-counter-order');const terminal=document.querySelector('.kiosk-terminal');if(!terminal)return;if(!button){button=document.createElement('button');button.id='next-counter-order';button.className='small-btn';terminal.appendChild(button);button.onclick=()=>{const next=sim.orders.find(o=>!o.accepted&&o.id!==sim.kioskJob?.id);if(next){selectCustomer(next.id);document.querySelector('#take-order')?.focus();}};}const next=sim.orders.find(o=>!o.accepted&&o.id!==sim.kioskJob?.id);button.hidden=!sim.kioskJob;button.disabled=!next;button.textContent=next?'Next counter order':'Waiting for next customer';if(sim.kioskJob)document.querySelector('#instruction').textContent='The kiosk is working independently. Select another customer and take their order at the counter.';};
